import argparse

from shelf import books, report, settings


def _settings_screen(chosen):
    """Show the current default sort; save `chosen`, or prompt for one."""
    current = settings.load_sort()
    if chosen is None:
        print("Default sort: %s" % current)
        for i, key in enumerate(settings.SORT_KEYS, start=1):
            print("  %d) %s" % (i, key))
        try:
            answer = input("Pick 1 or 2 (Enter keeps %s): " % current)
        except EOFError:
            answer = ""
        answer = answer.strip().lower()
        if answer == "":
            print("Kept %s" % current)
            return 0
        options = {str(i): key for i, key in enumerate(settings.SORT_KEYS, start=1)}
        options.update({key: key for key in settings.SORT_KEYS})
        chosen = options.get(answer)
        if chosen is None:
            print("Invalid choice %r; kept %s" % (answer, current))
            return 1
    settings.save_sort(chosen)
    print("Default sort: %s" % chosen)
    return 0


def main(argv=None):
    p = argparse.ArgumentParser(prog="shelf")
    sub = p.add_subparsers(dest="cmd", required=True)
    a = sub.add_parser("add")
    a.add_argument("title")
    a.add_argument("author")
    f = sub.add_parser("find")
    f.add_argument("query")
    l = sub.add_parser("list")
    l.add_argument("--sort", choices=settings.SORT_KEYS, default=None)
    sub.add_parser("report")
    s = sub.add_parser("settings")
    s.add_argument("--sort", choices=settings.SORT_KEYS, default=None)
    args = p.parse_args(argv)
    if args.cmd == "add":
        books.add(args.title, args.author)
    elif args.cmd == "find":
        for b in books.find(args.query):
            print("%s - %s" % (b["title"], b["author"]))
    elif args.cmd == "list":
        for b in books.sorted_by(args.sort or settings.load_sort()):
            print("%s - %s" % (b["title"], b["author"]))
    elif args.cmd == "report":
        print(report.summary())
    elif args.cmd == "settings":
        return _settings_screen(args.sort)
    return 0
